-- UUIDv7 ids, generated by the database (Postgres 17: Supabase has no 18, whose built-in
-- uuidv7() this replaces). Own name on purpose: on 18 a function called uuidv7() would be
-- shadowed by the built-in, and local/CI would no longer run the code production runs.
-- A random v4 UUID, first 6 bytes overwritten with Unix time in ms, version bits 4 -> 7.
-- Ordered across milliseconds; within the same millisecond the order is random (ids only
-- break ties after created_at, which needs uniqueness, not order).
CREATE FUNCTION gen_uuidv7() RETURNS uuid
LANGUAGE sql VOLATILE PARALLEL SAFE AS $$
  SELECT encode(
    set_bit(
      set_bit(
        overlay(
          uuid_send(gen_random_uuid())
          PLACING substring(int8send(floor(extract(epoch FROM clock_timestamp()) * 1000)::bigint) FROM 3)
          FROM 1 FOR 6
        ),
        52, 1
      ),
      53, 1
    ),
    'hex'
  )::uuid
$$;

