CREATE TABLE "users" (
    "id" UUID NOT NULL DEFAULT gen_uuidv7(),
    "name" TEXT NOT NULL,
    "email" TEXT NOT NULL,
    "email_verified" BOOLEAN NOT NULL DEFAULT false,
